local function drawPart(rectangles,lift)
 for _,v in ipairs(rectangles) do
  g.fillRect(v&511,((v>>9)&255)+lift,(v>>17)&511,(v>>26)&255)
 end
end
function p.update()
 local t=p.getCurrentTimeMilliseconds()
 while ni<=#notes and t>=notes[ni][1] do
  local n=notes[ni];lead:playNote(n[2],.85,n[3]);ni=ni+1
 end
 while bi<=#roots and t>=roots[bi][1] do
  bass:playNote(roots[bi][2],.85,.20);bi=bi+1
 end
 local enter=math.min(1,t/500)
 local lift=math.floor(-172*(1-enter)^3)
 if t<1700 then lift=lift+math.floor(math.sin(t/130)*2) end
 g.clear(g.kColorWhite);g.setColor(g.kColorBlack)
 drawPart(monster,lift)
 -- The gearbox belongs to the raster; the rotating arm is actual animation.
 local phase=math.min(t,2134)/2134*math.pi*8-math.pi/2
 local cx,cy=303,88+lift
 local hx=cx+math.floor(math.cos(phase)*17)
 local hy=cy+math.floor(math.sin(phase)*17)
 g.setColor(g.kColorWhite)
 for d=-3,3 do g.drawLine(cx,cy+d,hx,hy+d) end
 g.fillRect(hx-5,hy-8,11,17)
 g.setColor(g.kColorBlack)
 for d=-1,1 do g.drawLine(cx,cy+d,hx,hy+d) end
 g.fillRect(hx-3,hy-6,7,13);g.fillRect(cx-2,cy-2,5,5)
 g.setColor(g.kColorWhite);g.fillRect(hx-1,hy-4,2,5)
 g.setColor(g.kColorBlack)
 if t>=250 then
  local wordLift=math.floor(80*(1-math.min(1,(t-250)/450))^3)
  drawPart(wordmark,wordLift)
 end
 if t>=850 then
  g.drawText("BAD APPLE. GOOD GAMES.",137,230)
 end
end
